import test from 'node:test'
import assert from 'node:assert/strict'
import { DEFAULT_NAME, greet } from '../src/index.ts'

test('greet() with no argument greets the default name world', () => {
  assert.equal(DEFAULT_NAME, 'world')
  assert.equal(greet(), 'Hello, world!')
})

test('greet(undefined) greets the default name world', () => {
  assert.equal(greet(undefined), 'Hello, world!')
})

test('greet(name) greets the given name verbatim', () => {
  assert.equal(greet('Ada'), 'Hello, Ada!')
  assert.equal(greet('Ada Lovelace'), 'Hello, Ada Lovelace!')
})

test('greet rejects an empty name with TypeError', () => {
  assert.throws(() => greet(''), TypeError)
})

test('greet rejects a whitespace-only name with TypeError', () => {
  assert.throws(() => greet('   '), TypeError)
})
import test from 'node:test'
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const CLI = fileURLToPath(new URL('../src/cli.ts', import.meta.url))

function cli(...args: string[]): { status: number | null; stdout: string; stderr: string } {
  const result = spawnSync(process.execPath, ['--no-warnings', CLI, ...args], { encoding: 'utf8' })
  return { status: result.status, stdout: result.stdout, stderr: result.stderr }
}

test('--help prints usage on stdout and exits 0', () => {
  const result = cli('--help')
  assert.equal(result.status, 0)
  assert.ok(result.stdout.startsWith('Usage: greenfield-proof [name]'))
  assert.equal(result.stderr, '')
})

test('-h is the short help alias and exits 0', () => {
  const result = cli('-h')
  assert.equal(result.status, 0)
  assert.ok(result.stdout.startsWith('Usage: greenfield-proof [name]'))
})

test('an unknown option prints usage on stderr and exits 1', () => {
  const result = cli('--bogus')
  assert.equal(result.status, 1)
  assert.equal(result.stdout, '')
  assert.ok(result.stderr.startsWith('Unknown option: --bogus\nUsage: greenfield-proof [name]'))
})

test('an unknown option next to --help still exits 1 in either order', () => {
  for (const args of [['--help', '--bogus'], ['--bogus', '--help'], ['-h', '-x']]) {
    const result = cli(...args)
    assert.equal(result.status, 1, args.join(' '))
    assert.equal(result.stdout, '', args.join(' '))
    assert.ok(result.stderr.startsWith(`Unknown option: ${args.find((arg) => !['--help', '-h'].includes(arg))}\nUsage: greenfield-proof [name]`), args.join(' '))
  }
})

test('no argument prints the default greeting', () => {
  const result = cli()
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, world!\n')
  assert.equal(result.stderr, '')
})

test('a name argument prints its greeting', () => {
  const result = cli('Ada')
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, Ada!\n')
})

test('a blank name exits 1 with the TypeError message and usage', () => {
  const result = cli('   ')
  assert.equal(result.status, 1)
  assert.equal(result.stdout, '')
  assert.ok(result.stderr.startsWith('greet(name): name must be a non-blank string\nUsage: greenfield-proof [name]'))
})

test('more than one positional argument exits 1 with usage', () => {
  const result = cli('Ada', 'Grace')
  assert.equal(result.status, 1)
  assert.ok(result.stderr.includes('Too many arguments'))
  assert.ok(result.stderr.includes('Usage: greenfield-proof [name]'))
})
